from typing import Any


def S(customer, phone, year, make, model, part, category, outcome, sentiment, score,
      order, quoted, sold, topics, lost, days_ago, hour, summary, turns, strengths, improvements, coaching):
    """Compact scenario builder. `turns` alternate rep/customer starting with the rep."""
    t = [("rep" if i % 2 == 0 else "cust", txt) for i, txt in enumerate(turns)]
    words = sum(len(x[1].split()) for x in t)
    return {
        "customer": customer, "phone": phone, "year": year, "make": make, "model": model, "part": part,
        "category": category, "outcome": outcome, "sentiment": sentiment, "score": score,
        "order_value": float(order), "quoted_value": float(quoted), "parts_sold": sold, "topics": topics,
        "lost_reason": lost, "days_ago": days_ago, "hour": hour, "duration": int(words * 2.2),
        "summary": summary, "turns": t, "strengths": strengths, "improvements": improvements, "coaching": coaching,
    }


